// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ProposeChange Propose a change to a released document (scope changes:propose)
	// (POST /integration/v1/changes)
	ProposeChange(ctx context.Context, request ProposeChangeRequestObject) (ProposeChangeResponseObject, error)
	// GetProposedChange The status of one of your own proposals (scope changes:read)
	// (GET /integration/v1/changes/{changeId})
	GetProposedChange(ctx context.Context, request GetProposedChangeRequestObject) (GetProposedChangeResponseObject, error)
	// ListReleasedDocuments Released documents, by release time (scope documents:read)
	// (GET /integration/v1/documents)
	ListReleasedDocuments(ctx context.Context, request ListReleasedDocumentsRequestObject) (ListReleasedDocumentsResponseObject, error)
	// GetReleasedRevision One released revision with its rows (scope revisions:read)
	// (GET /integration/v1/documents/{documentId}/revisions/{revision})
	GetReleasedRevision(ctx context.Context, request GetReleasedRevisionRequestObject) (GetReleasedRevisionResponseObject, error)
	// CreateExport Queue an Excel export of a released revision (scope exports:create)
	// (POST /integration/v1/exports)
	CreateExport(ctx context.Context, request CreateExportRequestObject) (CreateExportResponseObject, error)
	// GetExport The state of one export job
	// (GET /integration/v1/exports/{exportId})
	GetExport(ctx context.Context, request GetExportRequestObject) (GetExportResponseObject, error)
	// DownloadExport Download the file of a finished export job
	// (GET /integration/v1/exports/{exportId}/file)
	DownloadExport(ctx context.Context, request DownloadExportRequestObject) (DownloadExportResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

